const readMCPAccessPolicyRules = `-- name: ReadMCPAccessPolicyRules :many
SELECT id, account_id, app_id, match_host, match_path, match_methods,
       match_headers, priority, enabled, kind, action, expires_at, match_expr, mode
FROM edge_rules WHERE account_id = $1::uuid AND kind = 'jwt'
ORDER BY id
`

type ReadMCPAccessPolicyRulesRow struct {
	ID           pgtype.UUID
	AccountID    pgtype.UUID
	AppID        pgtype.UUID
	MatchHost    string
	MatchPath    string
	MatchMethods []string
	MatchHeaders []byte
	Priority     int16
	Enabled      bool
	Kind         string
	Action       []byte
	ExpiresAt    pgtype.Timestamptz
	MatchExpr    []byte
	Mode         string
}

func (q *Queries) ReadMCPAccessPolicyRules(ctx context.Context, db DBTX, accountID pgtype.UUID) ([]ReadMCPAccessPolicyRulesRow, error) {
	rows, err := db.Query(ctx, readMCPAccessPolicyRules, accountID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReadMCPAccessPolicyRulesRow{}
	for rows.Next() {
		var i ReadMCPAccessPolicyRulesRow
		if err := rows.Scan(
			&i.ID,
			&i.AccountID,
			&i.AppID,
			&i.MatchHost,
			&i.MatchPath,
			&i.MatchMethods,
			&i.MatchHeaders,
			&i.Priority,
			&i.Enabled,
			&i.Kind,
			&i.Action,
			&i.ExpiresAt,
			&i.MatchExpr,
			&i.Mode,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const readMCPGatewayPromotionEvidence = `-- name: ReadMCPGatewayPromotionEvidence :one
WITH sampled AS (SELECT clock_timestamp()::timestamptz AS captured_at), position AS (
 SELECT GREATEST(
   COALESCE((SELECT MAX(id) FROM edge_rule_change_log WHERE account_ids @> ARRAY[$1::uuid]), 0),
   COALESCE((SELECT MAX(id) FROM edge_rule_change_log WHERE account_ids IS NULL), 0)
 )::bigint AS revision
), gateways AS (
 SELECT n.name, w.boot_id, w.last_change_id, w.observed_at
 FROM compute_nodes n LEFT JOIN gateway_edge_rule_watermarks w ON w.node_name = n.name
 WHERE n.active AND n.role IN ('compute-only', 'compute-node')
   AND n.gateway_target_url IS NOT NULL AND btrim(n.gateway_target_url) <> ''
)
SELECT position.revision, sampled.captured_at,
 COALESCE((SELECT jsonb_agg(jsonb_build_object('node_name', name, 'boot_id', boot_id, 'revision', last_change_id, 'observed_at', observed_at) ORDER BY name) FROM gateways), '[]'::jsonb)::jsonb AS gateways,
 (SELECT COUNT(*) FROM gateways)::bigint AS serving,
 (SELECT COUNT(*) FROM gateways WHERE observed_at IS NULL OR observed_at < sampled.captured_at - interval '10 seconds' OR observed_at > sampled.captured_at)::bigint AS stale,
 (SELECT COUNT(*) FROM gateways WHERE COALESCE(last_change_id, 0) < position.revision)::bigint AS pending
FROM position CROSS JOIN sampled
`

type ReadMCPGatewayPromotionEvidenceRow struct {
	Revision   int64
	CapturedAt pgtype.Timestamptz
	Gateways   []byte
	Serving    int64
	Stale      int64
	Pending    int64
}

func (q *Queries) ReadMCPGatewayPromotionEvidence(ctx context.Context, db DBTX, accountID pgtype.UUID) (ReadMCPGatewayPromotionEvidenceRow, error) {
	row := db.QueryRow(ctx, readMCPGatewayPromotionEvidence, accountID)
	var i ReadMCPGatewayPromotionEvidenceRow
	err := row.Scan(
		&i.Revision,
		&i.CapturedAt,
		&i.Gateways,
		&i.Serving,
		&i.Stale,
		&i.Pending,
	)
	return i, err
}

